    _D3DDISPLAYMODE GetClosestMode(const C2DExtentsI& resolution, long bit_depth, bool exclusive) const;
    CPixelFormat GetClosestDepthBufferFormat(const _D3DDISPLAYMODE& mode, long bit_depth) const;
