    return s;
}
static void Got(int id, UL a = 0, UL b = 0, UL c = 0)
{
    if (!g_armed) return;
    if (g_ngot < MAXEV) { Ev& e = g_got[g_ngot]; e.id = id; e.a = a; e.b = b; e.c = c; e.s = Live(); }
    ++g_ngot;
