            if (strcmp((const char*)(base + names[i] + 2), name)) continue;
            UL old; if (!VirtualProtect(&slots[i], 4, 4, &old)) return false;
            slots[i] = replacement; VirtualProtect(&slots[i], 4, old, &old);
