            if (!MHas()) { Want(E_LOCK, lock, 0); Want(E_GET); Want(E_FREE, (UL)g_single, m.Src); m.Src = 0; Want(E_UNLOCK, 0); }
            if (m.Used == g_s.chunk_size || file_finished)
            {
                UL size = m.Used;
                Want(E_LOCK, lock, 0);
