    }
    if (m.Src != 0) { Want(E_LOCK, lock, 0); Want(E_GET); Want(E_FREE, (UL)g_single, m.Src); m.Src = 0; Want(E_UNLOCK, 0); }
    Want(E_LOCK, lock, 0);
    for (int i = 0; i < g_s.nreads; ++i)
    {
        const RStep& r = g_s.reads[i];
        if ((UL)r.pos != m.SrcPos) continue;
