        memcpy(g_readmem[i], r.magic_ok ? "biz!" : (i & 1) ? "biz?" : "Biz!", 4); memcpy(g_readmem[i] + 4, &r.out_size, 4);
        g_readchunk[i].Mem = g_readmem[i];
