        p->FilePos = r.pos; p->TransferSize = r.size; p->PBufferChunk = &g_readchunk[i]; g_pread[i] = p;
        Node* n = (Node*)malloc(12); n->value[0] = (UL)p; n->prev = g_reads->prev; n->next = g_reads; g_reads->prev->next = n; g_reads->prev = n; g_rnode[i] = n;
    }
